// Biến object metadata thành các thẻ <head>
function renderHead(meta, baseUrl, path) {
  const title = meta.template ? meta.template.replace("%s", meta.title) : meta.title;
  const tags = [
    "<title>" + title + "</title>",
    '<meta name="description" content="' + meta.description + '">',
    '<link rel="canonical" href="' + baseUrl + path + '">',
    '<meta property="og:title" content="' + title + '">',
  ];
  return tags;
}

console.log(renderHead(
  { title: "Giới thiệu", template: "%s | Learn With Leo", description: "Về chúng tôi" },
  "https://lexi.example", "/about"
).join("\n"));

